"use client";

import * as React from "react";
import { Slider as SliderPrimitive } from "@base-ui/react/slider";

import { cn } from "@/lib/utils";
import { creamBevel, wellInset } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Burnished Slider: a recessed well track with a cream bevel range, the
 * primary's own face. Each thumb is a cream bevel knob in a copper rim.
 * Pass an array value for a range; the slider renders one thumb per value.
 */
const Slider = React.forwardRef<
  HTMLDivElement,
  WithClassName<SliderPrimitive.Root.Props>
>(({ className, defaultValue, value, min = 0, max = 100, ...props }, ref) => {
  const _values = Array.isArray(value)
    ? value
    : Array.isArray(defaultValue)
      ? defaultValue
      : [min];

  return (
    <SliderPrimitive.Root
      data-slot="slider"
      ref={ref}
      thumbAlignment="edge"
      defaultValue={defaultValue}
      value={value}
      min={min}
      max={max}
      className={cn(
        "relative w-full data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50",
        className,
      )}
      {...props}
    >
      <SliderPrimitive.Control className="relative flex h-6 w-full touch-none select-none items-center">
        <SliderPrimitive.Track
          data-slot="slider-track"
          className={cn("relative h-2 w-full grow overflow-hidden rounded-full", wellInset)}
        >
          <SliderPrimitive.Indicator
            data-slot="slider-range"
            className={cn("rounded-full", creamBevel)}
          />
        </SliderPrimitive.Track>
        {Array.from({ length: _values.length }, (_, index) => (
          <SliderPrimitive.Thumb
            data-slot="slider-thumb"
            key={index}
            className={cn(
              "block size-5 shrink-0 cursor-grab rounded-full border-2 border-transparent",
              "[background:var(--fill-primary)_padding-box,var(--ring-sheen)_border-box,conic-gradient(var(--ring-flow))_border-box] shadow-(--bevel-primary)",
              "transition-[box-shadow] duration-fast ease-(--ease-out) active:cursor-grabbing",
              "[@media(hover:hover)_and_(pointer:fine)]:hover:shadow-(--bevel-glow)",
              "has-[:focus-visible]:ring-3 has-[:focus-visible]:ring-ring",
              "data-[disabled]:pointer-events-none",
            )}
          />
        ))}
      </SliderPrimitive.Control>
    </SliderPrimitive.Root>
  );
});
Slider.displayName = "Slider";

export { Slider };
